// The automation watches a single fiscal host: Open Source Europe,
// whose host slug on Open Collective is 'europe'.
return [
  { json: { host_slug: 'europe', org: 'OSE' } },
];

// Flattens the per-host GraphQL responses into one item per pending
// application, shaped exactly like an ose_applications row.
const ORG_BY_HOST = { 'europe': 'OSE' };
const out = [];
for (const item of $input.all()) {
  const host = item.json.data && item.json.data.host;
  if (!host) {
    throw new Error('intake: unexpected GraphQL response: ' + JSON.stringify(item.json.errors || item.json).slice(0, 500));
  }
  for (const node of host.hostApplications.nodes) {
    const account = node.account || {};
    if (!account.slug) continue;
    const links = account.socialLinks || [];
    const repoLink = links.find((l) => ['GITHUB', 'GITLAB', 'GIT_REPOSITORY'].includes(l.type));
    const siteLink = links.find((l) => l.type === 'WEBSITE');
    const adminEmails = ((account.members || {}).nodes || [])
      .map((m) => (m.account || {}).email)
      .filter(Boolean);
    const custom = node.customData || {};
    out.push({ json: {
      slug: account.slug,
      org: ORG_BY_HOST[host.slug] || host.slug,
      host_slug: host.slug,
      collective_name: account.name || account.slug,
      collective_url: 'https://opencollective.com/' + account.slug,
      description: account.description || '',
      long_description: account.longDescription || '',
      repository_url: (repoLink || {}).url || '',
      website_url: (siteLink || {}).url || '',
      application_message: node.message || '',
      applicant_email: custom.email || custom.contactEmail || adminEmails[0] || '',
      applied_at: node.createdAt,
    }});
  }
}
return out;

// Pairs each status response with its state row (the HTTP node emits one
// response per input row, in order) and keeps only rows whose application
// was decided on Open Collective.
const rows = $('Still open?').all();
const out = [];
$input.all().forEach((item, i) => {
  const row = rows[i].json;
  const account = item.json.data && item.json.data.account;
  if (!account) return; // collective gone or renamed — leave the row for a human
  const requests = (account.hostApplicationRequests || {}).nodes || [];
  const forThisHost = requests.find((r) => r.host && r.host.slug === row.host_slug);
  if (!forThisHost) return;
  if (forThisHost.status === 'APPROVED' || forThisHost.status === 'REJECTED') {
    out.push({ json: {
      slug: row.slug,
      org: row.org,
      collective_name: row.collective_name,
      applicant_email: row.contact_email || row.applicant_email || '',
      decision: forThisHost.status.toLowerCase(),
    }, pairedItem: { item: i } });
  }
});
return out;

const TEMPLATES = {
  approved: `Subject: {{ collective_name }} is approved on Open Collective

Hi,

Good news: {{ collective_name }} has been approved as a fiscal-hosted collective under
{{ org_name }} on Open Collective.

You should have access to your collective page now. If anything looks wrong or you can't
get in, reply to this email and we'll sort it out.

Welcome aboard.

— {{ org_name }}`,
  rejected: `Subject: {{ collective_name }} — outcome of your application to {{ org_name }}

Hi,

We've reviewed the application for {{ collective_name }} and won't be taking it forward
as a fiscal-hosted collective under {{ org_name }} at this time.

This is about fit with what we host, not a judgement on the project. You're welcome to
apply again later if things change, or to look at another fiscal host that might be a
closer match.

If you'd like more detail on the decision, reply to this email.

— {{ org_name }}`
};
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
if (!row.applicant_email) throw new Error(`decision email: no address for ${row.slug}`);
const raw = TEMPLATES[row.decision];
if (!raw) throw new Error(`decision email: unknown decision "${row.decision}" for ${row.slug}`);
const vars = { collective_name: row.collective_name, org_name: ORG_NAMES[row.org] || row.org };
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`decision email: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = raw.indexOf('\n');
let subject = render(raw.slice('Subject: '.length, cut));
const body = render(raw.slice(cut).trimStart());
// DRY_RUN fails safe: only the exact string `false` releases mail to the applicant. Unset,
// empty, `1`, `yes` or a trailing space all suppress, so a dropped or mistyped line in .env
// cannot quietly start mailing real people. Going live is the deliberate act of writing
// DRY_RUN=false.
const suppressed = String($env.DRY_RUN || '').trim().toLowerCase() !== 'false';
if (suppressed) subject = `[DRY_RUN → would have gone to ${row.applicant_email}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : row.applicant_email;
if (!to) throw new Error('decision email: DRY_RUN is not "false", so the email is suppressed, but DRY_RUN_RECIPIENT is empty');
return { json: { slug: row.slug, to, subject, body, suppressed } };

// One Slack message per new application. Its timestamp becomes the thread anchor every
// later stage replies to, so it is stored on the row in the next node.
//
// The name, URL and description come from the collective's public Open Collective page,
// which the applicant writes. They are data, not markup: <!channel> in a name, or a masked
// link like <https://evil.example|opencollective.com/theirs> in a description, would
// otherwise be honoured by Slack in the reviewers' channel. Escape the three characters
// Slack treats as control characters, & first so the other two are not escaped twice. Only
// those values go through escapeSlack: the fixed wording keeps its :incoming_envelope: and
// its *bold*, and org resolves from our own host list.
const ORG_NAMES = { OSE: 'Open Source Europe' };

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const channel = $env.SLACK_CHANNEL || '';
if (!channel) throw new Error('application parent message: SLACK_CHANNEL is empty');
return $input.all().map((item) => {
  const row = item.json;
  const org = ORG_NAMES[row.org] || row.org;
  const text = [
    `:incoming_envelope: *${escapeSlack(row.collective_name)}* applied to ${org}`,
    row.collective_url ? escapeSlack(row.collective_url) : null,
    row.description ? `> ${escapeSlack(row.description)}` : null,
  ].filter(Boolean).join('\n');
  return { json: { slug: row.slug, channel, text } };
});

// Rows whose parent message never got posted are skipped rather than posted loose in the
// channel: a reply with no thread_ts lands in the channel with no context.
const LABELS = { approved: ':white_check_mark: Approved on Open Collective',
                 rejected: ':x: Rejected on Open Collective' };

// Both known decisions are fixed wording. The fallback interpolates row.decision, which
// arrives from the Open Collective API and can also be typed by hand into the data table,
// so it is escaped: & first, then < and >, so Slack reads it as text and not as a control
// sequence.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const label = LABELS[row.decision] || `Decision recorded: ${escapeSlack(row.decision)}`;
    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      reaction: row.decision === 'approved' ? 'white_check_mark' : 'x',
      text: label,
    } };
  });

// The Slack post above runs with onError continueRegularOutput, so a Slack outage never
// holds up an application. A failed post arrives here as { error: ... } with no
// message.ts, and writing that would store an anchor pointing at nothing. Drop those
// items: the row keeps null identifiers, and every later stage already skips a row that
// has none.
const rendered = $('Render application parent message').all();
return $input.all()
  .map((item, index) => ({ item, slug: rendered[index] ? rendered[index].json.slug : null }))
  .filter(({ item, slug }) => Boolean(slug) && Boolean(item.json && item.json.message && item.json.message.ts))
  .map(({ item, slug }) => ({ json: {
    slug,
    channel: item.json.channel,
    thread_ts: item.json.message.ts,
  } }));
